var pinnedELKCategories = []LayoutCategoryDefinition{
	{ID: "layered", Name: "Layered", Description: "The layer-based method was introduced by Sugiyama, Tagawa and Toda in 1981. It emphasizes the direction of edges by pointing as many edges as possible into the same direction. The nodes are arranged in layers, which are sometimes called \"hierarchies\", and then reordered such that the number of edge crossings is minimized. Afterwards, concrete coordinates are computed for the nodes and edge bend points.", KnownLayouters: []string{"layered"}},
	{ID: "orthogonal", Name: "Orthogonal", Description: "Orthogonal methods that follow the \"topology-shape-metrics\" approach by Batini, Nardelli and Tamassia '86. The first phase determines the topology of the drawing by applying a planarization technique, which results in a planar representation of the graph. The orthogonal shape is computed in the second phase, which aims at minimizing the number of edge bends, and is called orthogonalization. The third phase leads to concrete coordinates for nodes and edge bend points by applying a compaction method, thus defining the metrics.", KnownLayouters: []string{}},
	{ID: "force", Name: "Force", Description: "Layout algorithms that follow physical analogies by simulating a system of attractive and repulsive forces. The first successful method of this kind was proposed by Eades in 1984.", KnownLayouters: []string{"stress", "force"}},
	{ID: "circle", Name: "Circle", Description: "Circular layout algorithms emphasize cycles or biconnected components of a graph by arranging them in circles. This is useful if a drawing is desired where such components are clearly grouped, or where cycles are shown as prominent OPTIONS of the graph.", KnownLayouters: []string{}},
	{ID: "tree", Name: "Tree", Description: "Specialized layout methods for trees, i.e. acyclic graphs. The regular structure of graphs that have no undirected cycles can be emphasized using an algorithm of this type.", KnownLayouters: []string{"mrtree"}},
	{ID: "planar", Name: "Planar", Description: "Algorithms that require a planar or upward planar graph. Most of these algorithms are theoretically interesting, but not practically usable.", KnownLayouters: []string{}},
	{ID: "radial", Name: "Radial", Description: "Radial layout algorithms usually position the nodes of the graph on concentric circles.", KnownLayouters: []string{"radial"}},
	{ID: "", Name: "Other", Description: "", KnownLayouters: []string{"fixed", "box", "random", "sporeOverlap", "sporeCompaction", "rectpacking"}},
}

